+  for (final m in _strikeProtected.allMatches(s)) {
+    out.write(_applyStrike(s.substring(last, m.start)));
+    out.write(m.group(0));
+    last = m.end;
+  }
+  out.write(_applyStrike(s.substring(last)));
+  return out.toString();
