+  r'`[^`]*`|\{\{.*?\}\}|\{code[^}]*\}.*?\{code\}|https?://\S+',
+  dotAll: true,
+);
+
+final RegExp _strikeSpan = RegExp(r'~~(?=\S)(.+?)(?<=\S)~~');
+
+String _applyStrike(String segment) =>
+    segment.replaceAllMapped(_strikeSpan, (m) => '-${m.group(1)}-');
