  return null;
}

/// Inline emphasis/code tags (and unknown tags: children verbatim).
String _wrapInlineStyle(_XmlNode node, String inner) {
  switch (node.name) {
    case 'strong':
    case 'b':
      return '**$inner**';
    case 'em':
    case 'i':
      return '*$inner*';
    case 'del':
    case 'strike':
    case 's':
      return '~~$inner~~';
    case 'span':
      if (_isLineThrough(node)) return '~~$inner~~';
      return inner;
    case 'code':
      return '`${node.content}`';
  }
